shellCommands.command:
python3 - <<'EOF'
p='src/App.tsx'
s=open(p).read()
s=s.replace("""function LayoutHeaderCellsIcon() {
    return (
        <Text color="secondary">
            <LayoutHeaderCells width={64} height={64} />
        </Text>
    );
}

""","")
s=s.replace("image={<LayoutHeaderCellsIcon />}","image={<Icon data={LayoutHeaderCells} size={64} className=\"page__placeholder-icon\" />}")
s=s.replace("import {Flex, PlaceholderContainer, Text} from","import {Flex, Icon, PlaceholderContainer, Text} from")
open(p,'w').write(s)
EOF
cat > src/App.css <<'EOF'
html,
body,
#root {
    height: 100%;
    margin: 0;
}

.page {
    box-sizing: border-box;
    height: 100vh;
    min-height: 480px;
    min-width: 0;
    padding: var(--g-spacing-6) var(--g-spacing-8) var(--g-spacing-4);
}

.page__title {
    flex-shrink: 0;
    margin: 0;
}

.page__placeholder {
    flex: 1;
    min-height: 0;
}

.page__placeholder-icon {
    color: var(--g-color-text-secondary);
}

.orders {
    flex: 1;
    min-height: 0;
    min-width: 0;
}

.orders__toolbar {
    flex-shrink: 0;
}

.orders__spacer {
    flex: 1;
}

/* The table scrolls inside its own container (both axes); the page and the aside stay put. */
.orders__scroll {
    flex: 1;
    min-height: 0;
    min-width: 0;
    overflow: auto;
    border: 1px solid var(--g-color-line-generic);
    border-radius: var(--g-border-radius-l);
    background: var(--g-color-base-background);

    /* Theme-aware drag-and-drop visuals instead of the hard-coded defaults (#fff, #4d8bff). */
    --gt-table-reordering-insertion-line-color: var(--g-color-line-brand);
    --gt-table-drag-overlay-background: var(--g-color-base-float);
    --gt-table-drag-overlay-shadow: 0 3px 12px var(--g-color-sfx-shadow);
}

.orders__table {
    min-width: 100%;
}

.orders__table tbody tr {
    cursor: pointer;
}

@media (max-width: 600px) {
    .page {
        padding: var(--g-spacing-4) var(--g-spacing-3) var(--g-spacing-3);
    }
}
EOF
npx tsc --noEmit 2>&1 | head -30

node -e '
